package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class XmlDeclaration_getWholeDeclaration_TriageGen1Test {

    @Test
    public void test_xml_with_version_and_encoding_return_xml_with_version_and_encoding() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.add("version", "1.0");
        xmlDeclaration.attributes.add("encoding", "UTF-8");
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("xml version=\"1.0\" encoding=\"UTF-8\"", result);
    }

    @Test
    public void test_xml_with_only_version_return_xml_with_version() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.add("version", "1.0");
        assertNull(xmlDeclaration.attributes.get("encoding"));
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("xml version=\"1.0\"", result);
    }

    @Test
    public void test_xml_with_only_encoding_return_xml_with_encoding() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.add("encoding", "UTF-8");
        assertNull(xmlDeclaration.attributes.get("version"));
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("xml encoding=\"UTF-8\"", result);
    }

    @Test
    public void test_xml_with_no_version_or_encoding_return_xml() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        assertNull(xmlDeclaration.attributes.get("version"));
        assertNull(xmlDeclaration.attributes.get("encoding"));
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("xml", result);
    }

    @Test
    public void test_xml_with_version_and_encoding_and_other_attributes_return_xml_with_version_encoding_and_other_attributes() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        xmlDeclaration.attributes.add("version", "1.0");
        xmlDeclaration.attributes.add("encoding", "UTF-8");
        xmlDeclaration.attributes.add("other", "value");
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("xml version=\"1.0\" encoding=\"UTF-8\" other=\"value\"", result);
    }

    @Test
    public void test_not_xml_declaration_return_original_name() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("not-xml", null, false);
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("not-xml", result);
    }

    @Test
    public void test_xml_declaration_with_no_name_return_original_name() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration(null, null, false);
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("", result);
    }

    @Test
    public void test_xml_declaration_with_empty_name_return_original_name() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("", null, false);
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("", result);
    }

    @Test
    public void test_xml_declaration_with_attributes_but_not_xml_name_return_original_name() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("not-xml", null, false);
        xmlDeclaration.attributes.add("version", "1.0");
        xmlDeclaration.attributes.add("encoding", "UTF-8");
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("not-xml", result);
    }
}
